    if (tl_cfg_func < PF_COUNT) begin
        if (L_TILE) begin
            case (tl_cfg_add[3:0])
                4'h0: begin
                    cfg_ido_request_en[tl_cfg_func +: 1] <= tl_cfg_ctl[31];
