            // pipeline
            input_a_reg_1 <= input_a_reg_0;
            input_b_reg_1 <= input_b_reg_0;

            // multiply
            output_reg_0 <= $signed(input_a_reg_1) * $signed(input_b_reg_1);

            // pipeline
            output_reg_1 <= output_reg_0;
        end
    end
