        6'h25: G = 4;
        6'h26: G = 7;
        6'h27: G = 10;
        6'h28: G = 13;
        6'h29: G = 0;
        6'h2a: G = 3;
        6'h2b: G = 6;
        6'h2c: G = 9;
        6'h2d: G = 12;
        6'h2e: G = 15;
        6'h2f: G = 2;
        6'h30: G = 0;
        6'h31: G = 7;
        6'h32: G = 14;
        6'h33: G = 5;
        6'h34: G = 12;
        6'h35: G = 3;
        6'h36: G = 10;
        6'h37: G = 1;
        6'h38: G = 8;
        6'h39: G = 15;
        6'h3a: G = 6;
        6'h3b: G = 13;
        6'h3c: G = 4;
        6'h3d: G = 11;
        6'h3e: G = 2;
        6'h3f: G = 9;
      endcase // case (round)
  endfunction // G

  function [31 : 0] byteflip(input  [31 : 0] w);
    byteflip = {w[7 : 0], w[15 : 8],  w[23 : 16], w[31 : 24]};
  endfunction // byteflip


  //----------------------------------------------------------------
  // Concurrent connectivity for ports etc.
  //----------------------------------------------------------------
  assign ready  = ready_reg;

  assign digest = {byteflip(h0_reg), byteflip(h1_reg),
                   byteflip(h2_reg), byteflip(h3_reg)};


  //----------------------------------------------------------------
  // reg_update
  //
  // Update functionality for all registers in the core.
  // All registers are positive edge triggered with asynchronous
  // active low reset.
  //----------------------------------------------------------------
  always @ (posedge clk or negedge reset_n)
    begin: reg_update
      integer i;

      if (!reset_n)
        begin
          for (i = 0 ; i < 16 ; i = i + 1)
            block_reg[i] <= 32'h0;

          h0_reg            <= 32'h0;
          h1_reg            <= 32'h0;
          h2_reg            <= 32'h0;
          h3_reg            <= 32'h0;
          a_reg             <= 32'h0;
          b_reg             <= 32'h0;
          c_reg             <= 32'h0;
          d_reg             <= 32'h0;
          ready_reg         <= 1'h1;
          round_ctr_reg     <= 7'h0;
          md5_core_ctrl_reg <= CTRL_IDLE;
        end
      else
        begin
          if (ready_we)
            ready_reg <= ready_new;

          if (block_we)
            begin
              block_reg[00] <= block[511 : 480];
              block_reg[01] <= block[479 : 448];
              block_reg[02] <= block[447 : 416];
              block_reg[03] <= block[415 : 384];
              block_reg[04] <= block[383 : 352];
              block_reg[05] <= block[351 : 320];
              block_reg[06] <= block[319 : 288];
              block_reg[07] <= block[287 : 256];
              block_reg[08] <= block[255 : 224];
              block_reg[09] <= block[223 : 192];
              block_reg[10] <= block[191 : 160];
              block_reg[11] <= block[159 : 128];
              block_reg[12] <= block[127 : 096];
              block_reg[13] <= block[095 : 064];
              block_reg[14] <= block[063 : 032];
              block_reg[15] <= block[031 : 000];
            end

          if (h_we)
            begin
              h0_reg <= h0_new;
              h1_reg <= h1_new;
              h2_reg <= h2_new;
              h3_reg <= h3_new;
            end

          if (a_d_we)
            begin
              a_reg <= a_new;
              b_reg <= b_new;
              c_reg <= c_new;
              d_reg <= d_new;
            end

          if (round_ctr_we)
            round_ctr_reg <= round_ctr_new;

          if (md5_core_ctrl_we)
            md5_core_ctrl_reg <= md5_core_ctrl_new;
        end
    end // reg_update


  //----------------------------------------------------------------
  // md5_dp
  //----------------------------------------------------------------
  always @*
    begin : md5_dp
      reg [31 : 0] f;
      reg [31 : 0] k;
      reg [3 : 0]  g;
      reg [31 : 0] w;
      reg [31 : 0] tmp_b0;
      reg [31 : 0] lr;
      reg [31 : 0] tmp_b2;

      h0_new = 32'h0;
      h1_new = 32'h0;
      h2_new = 32'h0;
      h3_new = 32'h0;
      h_we   = 1'h0;

      a_new  = 32'h0;
      b_new  = 32'h0;
      c_new  = 32'h0;
      d_new  = 32'h0;
      a_d_we = 1'h0;

      f = F(b_reg, c_reg, d_reg, round_ctr_reg[5 : 0]);
      g = G(round_ctr_reg[5 : 0]);
      w = block_reg[g];
      k = K(round_ctr_reg[5 : 0]);

      tmp_b0 = a_reg + f + w + k;
      lr = rotate(tmp_b0, round_ctr_reg[5 : 0]);
      tmp_b2 = lr + b_reg;


      if (init_state)
        begin
          h0_new  = A0;
          h1_new  = B0;
          h2_new  = C0;
          h3_new  = D0;
          h_we    = 1'h1;
        end

      if (update_state)
        begin
          h0_new  = h0_reg + a_reg;
          h1_new  = h1_reg + b_reg;
          h2_new  = h2_reg + c_reg;
          h3_new  = h3_reg + d_reg;
          h_we    = 1'h1;
        end

      if (init_round)
        begin
          a_new = h0_reg;
          b_new = h1_reg;
          c_new = h2_reg;
          d_new = h3_reg;
          a_d_we = 1'h1;
        end

      if (update_round)
        begin
          a_new  = d_reg;
          b_new  = tmp_b2;
          c_new  = b_reg;
          d_new  = c_reg;
          a_d_we = 1'h1;
        end
    end


  //----------------------------------------------------------------
  // round_ctr
  //----------------------------------------------------------------
  always @*
    begin : round_ctr
      round_ctr_new = 7'h0;
      round_ctr_we  = 1'h0;

      if (round_ctr_rst)
        begin
          round_ctr_new = 7'h0;
          round_ctr_we  = 1'h1;
        end

      if (round_ctr_inc)
        begin
          round_ctr_new = round_ctr_reg + 1'h1;
          round_ctr_we  = 1'h1;
        end
    end


  //----------------------------------------------------------------
  // md5_core_ctrl
  //----------------------------------------------------------------
  always @*
    begin : md5_core_ctrl
      ready_new         = 1'h0;
      ready_we          = 1'h0;
      block_we          = 1'h0;
      round_ctr_inc     = 1'h0;
      round_ctr_rst     = 1'h0;
      init_state        = 1'h0;
      update_state      = 1'h0;
      init_round        = 1'h0;
      update_round      = 1'h0;
      md5_core_ctrl_new = CTRL_IDLE;
      md5_core_ctrl_we  = 1'h0;


      case (md5_core_ctrl_reg)
        CTRL_IDLE:
          begin
            if (init)
              begin
                init_state = 1'h1;
              end

            if (next)
              begin
                init_round        = 1'h1;
                block_we          = 1'h1;
                round_ctr_rst     = 1'h1;
                ready_new         = 1'h0;
                ready_we          = 1'h1;
                md5_core_ctrl_new = CTRL_NEXT;
                md5_core_ctrl_we  = 1'h1;
              end
          end


        CTRL_NEXT:
          begin
            if (round_ctr_reg < NUM_ROUNDS)
              begin
                update_round  = 1'h1;
                round_ctr_inc = 1'h1;
              end
            else
              begin
                update_state      = 1'h1;
                ready_new         = 1'h1;
                ready_we          = 1'h1;
                md5_core_ctrl_new = CTRL_IDLE;
                md5_core_ctrl_we  = 1'h1;
              end
          end


        default:
          begin

          end
      endcase // case (md5_core_ctrl_reg)

    end // md5_core_ctrl
endmodule // md5_core

